package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.AuthFailure;import com.fasterxml.jackson.databind.ObjectMapper;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class SaleServiceTest {SaleService service=new SaleService(mock(SaleRepository.class),mock(CashRepository.class),mock(BusinessTransactions.class),new ObjectMapper());BigDecimal n(String v){return new BigDecimal(v);}Payment payment(String medio,String amount,String received,String operation){return new Payment(medio,n(amount),received==null?null:n(received),operation,null,null);}
 @Test void acceptsSplitPaymentsExactly(){service.validatePayments(List.of(payment("EFECTIVO","5","10",null),payment("YAPE","5",null,"12345678")),n("10"));}
 @Test void rejectsWrongTotalAndDuplicateMedium(){assertThatThrownBy(()->service.validatePayments(List.of(payment("EFECTIVO","9","10",null)),n("10"))).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.validatePayments(List.of(payment("EFECTIVO","5","5",null),payment("EFECTIVO","5","5",null)),n("10"))).isInstanceOf(AuthFailure.class);}
 @Test void rejectsShortCashAndFiadoMixedWithCash(){assertThatThrownBy(()->service.validatePayments(List.of(payment("EFECTIVO","10","9",null)),n("10"))).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.validatePayments(List.of(payment("CREDITO","5",null,null),payment("EFECTIVO","5","5",null)),n("10"))).isInstanceOf(AuthFailure.class);}
 @Test void validatesOperationNumbers(){assertThatThrownBy(()->service.validatePayments(List.of(payment("YAPE","10",null,"abc")),n("10"))).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.validatePayments(List.of(payment("DEBITO","10",null," ")),n("10"))).isInstanceOf(AuthFailure.class);}
}
